/* ---------------- Account credentials ---------------- */
function genPassword() {
  const a = 'ABCDEFGHJKLMNPQRSTUVWXYZ',
    b = 'abcdefghijkmnpqrstuvwxyz',
    d = '23456789';
  const pick = s => s[Math.floor(Math.random() * s.length)];
  return pick(a) + pick(b) + pick(b) + pick(b) + pick(d) + pick(d) + pick('!@#$');
}
